import json
rec = []
def ham(a, b):
    return bin(a ^ b).count("1")
def write(c, u):
    for r in rec:
        if ham(r[0], c) <= 1:
            r[2] = r[2] / 2
    rec.append([c, u, 1.0])
for c, u in [(12, 4), (13, 9), (100, 2), (12, 6), (44, 1)]:
    write(c, u)
best = max((r for r in rec if r[0] == 12), key=lambda r: r[2])
print(json.dumps({"weights": [r[2] for r in rec], "answer_12": best[1]}))
